import { InjectionToken } from '@angular/core';

export type RmNgPdfThemePreference = 'light' | 'dark' | 'system';

export interface RmNgPdfThemeColors {
  accent?: Partial<{
    primary: string;
    primaryHover: string;
    primaryActive: string;
    primaryLight: string;
    primaryForeground: string;
  }>;
  background?: Partial<{
    app: string;
    surface: string;
    surfaceAlt: string;
    elevated: string;
    overlay: string;
    input: string;
  }>;
  foreground?: Partial<{
    primary: string;
    secondary: string;
    muted: string;
    disabled: string;
    onAccent: string;
  }>;
  interactive?: Partial<{
    hover: string;
    active: string;
    selected: string;
    focus: string;
  }>;
  border?: Partial<{
    default: string;
    subtle: string;
    strong: string;
  }>;
  state?: Partial<{
    error: string;
    errorLight: string;
    warning: string;
    warningLight: string;
    success: string;
    successLight: string;
    info: string;
    infoLight: string;
  }>;
}

export type RmNgPdfThemeConfig = {
  preference?: RmNgPdfThemePreference;
  light?: RmNgPdfThemeColors;
  dark?: RmNgPdfThemeColors;
};

export interface RmNgPdfViewerConfig {
  src?: string;
  theme?: RmNgPdfThemeConfig;
  disabledCategories?: string[];
  [key: string]: unknown; // Allow additional config options to be passed through
}

export interface RmNgPdfViewerGlobalConfig extends RmNgPdfViewerConfig {
  height?: string;
  syncTheme?: boolean;
  themeStorageKey?: string; // Key for localStorage to persist theme preference
}

export const RM_NG_PDF_VIEWER_CONFIG = new InjectionToken<RmNgPdfViewerGlobalConfig>(
  'RM_NG_PDF_VIEWER_CONFIG',
);

export const provideRmNgPdfViewerConfig = (config?: RmNgPdfViewerGlobalConfig) => ({
  provide: RM_NG_PDF_VIEWER_CONFIG,
  useValue: config ?? {},
});
