import {
  afterNextRender,
  ChangeDetectionStrategy,
  Component,
  DestroyRef,
  DOCUMENT,
  effect,
  ElementRef,
  inject,
  input,
  output,
  PendingTasks,
  PLATFORM_ID,
  signal,
  TemplateRef,
  viewChild,
} from '@angular/core';
import { isPlatformBrowser, NgTemplateOutlet } from '@angular/common';
import { RM_NG_PDF_VIEWER_CONFIG, RmNgPdfThemeConfig, RmNgPdfViewerConfig } from './rm-ng-pdf-viewer.config';
import { EmbedPdfContainer } from '@embedpdf/snippet';

@Component({
  selector: 'rm-ng-pdf-viewer',
  imports: [NgTemplateOutlet],
  template: `
    <div class="rm-pdf-viewer-wrapper" [style.height]="height()">
      @if (isLoading()) {
        <div class="rm-pdf-viewer-loading-container">
          @if (loadingTemplate()) {
            <ng-container [ngTemplateOutlet]="loadingTemplate()!"></ng-container>
          } @else if (showSkeleton()) {
            <div class="rm-pdf-viewer-skeleton">
              <div class="rm-skeleton-toolbar">
                <div class="rm-skeleton-item button"></div>
                <div class="rm-skeleton-item button"></div>
                <div class="rm-skeleton-spacer"></div>
                <div class="rm-skeleton-item search"></div>
                <div class="rm-skeleton-item button"></div>
              </div>
              <div class="rm-skeleton-content">
                <div class="rm-skeleton-sidebar" [style.display]="showThumbnails() ? 'block' : 'none'">
                  <div class="rm-skeleton-item thumb"></div>
                  <div class="rm-skeleton-item thumb"></div>
                  <div class="rm-skeleton-item thumb"></div>
                </div>
                <div class="rm-skeleton-page-area">
                  <div class="rm-skeleton-page"></div>
                </div>
              </div>
            </div>
          } @else {
            <div class="rm-pdf-viewer-default-loader">Loading PDF...</div>
          }
          
          @if (showProgressBar() && loadingProgress() > 0 && loadingProgress() < 100) {
            <div class="rm-pdf-viewer-progress-bar" [style.width.%]="loadingProgress()"></div>
          }
        </div>
      }

      @if (error()) {
        <div class="rm-pdf-viewer-error">
          @if (errorTemplate()) {
            <ng-container [ngTemplateOutlet]="errorTemplate()!" [ngTemplateOutletContext]="{ $implicit: error() }"></ng-container>
          } @else {
            <div class="rm-pdf-viewer-default-error">
              {{ error()?.message || 'An error occurred while loading the PDF.' }}
            </div>
          }
        </div>
      }

      <div #container [style.display]="isLoading() || error() ? 'none' : 'block'" [style.height]="'100%'"></div>

      @if (showFullscreenButton() && !isLoading() && !error()) {
        <button class="rm-fullscreen-button" (click)="toggleFullscreen()" title="Toggle Fullscreen">
          <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </button>
      }
    </div>
  `,
  styles: `
    :host {
      display: block;
    }
    .rm-pdf-viewer-wrapper {
      position: relative;
      width: 100%;
      overflow: hidden;
      background-color: #f5f5f5;
    }
    .rm-pdf-viewer-loading-container,
    .rm-pdf-viewer-error {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      z-index: 1;
    }
    .rm-pdf-viewer-progress-bar {
      position: absolute;
      top: 0;
      left: 0;
      height: 3px;
      background-color: #2196f3;
      transition: width 0.2s ease-in-out;
      z-index: 10;
    }
    .rm-pdf-viewer-skeleton {
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      background: #fff;
    }
    .rm-skeleton-toolbar {
      height: 48px;
      padding: 0 16px;
      display: flex;
      align-items: center;
      gap: 12px;
      border-bottom: 1px solid #eee;
      background: #f8f9fa;
    }
    .rm-skeleton-content {
      flex: 1;
      display: flex;
      overflow: hidden;
    }
    .rm-skeleton-sidebar {
      width: 200px;
      border-right: 1px solid #eee;
      padding: 16px;
      background: #fcfcfc;
    }
    .rm-skeleton-page-area {
      flex: 1;
      padding: 24px;
      display: flex;
      justify-content: center;
      background: #e9ecef;
      overflow: hidden;
    }
    .rm-skeleton-page {
      width: 80%;
      max-width: 800px;
      height: 100%;
      background: #fff;
      box-shadow: 0 2px 8px rgba(0,0,0,0.1);
      animation: rm-skeleton-pulse 1.5s infinite ease-in-out;
    }
    .rm-skeleton-item {
      background: #e0e0e0;
      border-radius: 4px;
      animation: rm-skeleton-pulse 1.5s infinite ease-in-out;
    }
    .rm-skeleton-item.button { width: 32px; height: 32px; }
    .rm-skeleton-item.search { width: 150px; height: 32px; }
    .rm-skeleton-item.thumb { width: 100%; height: 150px; margin-bottom: 16px; }
    .rm-skeleton-spacer { flex: 1; }

    .rm-fullscreen-button {
      position: absolute;
      bottom: 16px;
      right: 16px;
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: #fff;
      border: 1px solid #ddd;
      box-shadow: 0 2px 8px rgba(0,0,0,0.1);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      color: #555;
      transition: all 0.2s;
      z-index: 5;
    }
    .rm-fullscreen-button:hover {
      background: #f8f9fa;
      color: #2196f3;
      transform: scale(1.05);
    }
    
    @keyframes rm-skeleton-pulse {
      0% { opacity: 1; }
      50% { opacity: 0.4; }
      100% { opacity: 1; }
    }

    .rm-pdf-viewer-default-loader {
      flex: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: sans-serif;
      color: #666;
    }
    .rm-pdf-viewer-default-error {
      flex: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      font-family: sans-serif;
      color: #d32f2f;
      padding: 1rem;
      text-align: center;
    }
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RmNgPdfViewer {
  private readonly globalConfig = inject(RM_NG_PDF_VIEWER_CONFIG, { optional: true });
  private readonly platformId = inject(PLATFORM_ID);
  private readonly doc = inject(DOCUMENT);
  private readonly elementRef = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly destroyRef = inject(DestroyRef);
  private readonly pendingTasks = inject(PendingTasks);

  private observer: MutationObserver | null = null;
  private readonly destroyed = signal(false);
  private currentObjectUrl: string | null = null;

  readonly src = input<string | Uint8Array | Blob>(this.globalConfig?.src || '');
  readonly height = input<string>(this.globalConfig?.height || '650px');
  readonly theme = input<RmNgPdfThemeConfig | undefined>(this.globalConfig?.theme);
  readonly syncTheme = input<boolean>(this.globalConfig?.syncTheme ?? true);
  readonly themeStorageKey = input<string | undefined>(this.globalConfig?.themeStorageKey);
  readonly config = input<RmNgPdfViewerConfig | undefined>();
  readonly lazy = input<boolean>(true); // Lazy load by default when in viewport

  readonly loadingTemplate = input<TemplateRef<any> | null>(null);
  readonly errorTemplate = input<TemplateRef<any> | null>(null);
  readonly showSkeleton = input<boolean>(true);
  readonly showProgressBar = input<boolean>(true);
  readonly showThumbnails = input<boolean>(false);
  readonly fullscreen = input<boolean>(false);
  readonly showFullscreenButton = input<boolean>(false);

  readonly onReady = output<EmbedPdfContainer>();
  readonly onError = output<Error>();
  readonly onPageChange = output<number>();
  readonly onZoomChange = output<number>();
  readonly onSearchMatch = output<any>();
  readonly onProgress = output<number>();

  readonly pdfContainer = signal<EmbedPdfContainer | undefined>(undefined);
  readonly containerElement = viewChild<ElementRef<HTMLDivElement>>('container');
  readonly isLoading = signal<boolean>(false);
  readonly error = signal<Error | null>(null);
  readonly loadingProgress = signal<number>(0);

  constructor() {
    this.destroyRef.onDestroy(() => {
      this.observer?.disconnect();
      this.observer = null;
      this.destroyed.set(true);
      this.revokeCurrentUrl();
    });

    afterNextRender(() => {
      if (!isPlatformBrowser(this.platformId)) {
        return;
      }

      if (this.lazy()) {
        this.setupIntersectionObserver();
      } else {
        this.initViewer();
      }
    });

    effect(() => {
      const newSrc = this.src();
      const container = this.pdfContainer();
      if (container && newSrc) {
        this.loadNewSrc(newSrc);
      }
    });

    effect(() => {
      const thumbnails = this.showThumbnails();
      const container = this.pdfContainer();
      if (container) {
        this.updateThumbnailsVisibility(container, thumbnails);
      }
    });

    effect(() => {
      const isFullscreen = this.fullscreen();
      const container = this.pdfContainer();
      if (container) {
        this.updateFullscreenState(container, isFullscreen);
      }
    });
  }

  private async loadNewSrc(src: string | Uint8Array | Blob) {
    const container = this.pdfContainer();
    if (!container) return;

    this.isLoading.set(true);
    this.loadingProgress.set(0);
    this.error.set(null);

    const registry = await container.registry;
    const docManager = registry.getPlugin('document-manager') as any;
    
    if (docManager && docManager.provides) {
      const capability = docManager.provides();
      let task: any;

      if (typeof src === 'string') {
        task = capability.openDocumentUrl({ url: src });
      } else if (src instanceof Blob) {
        const buffer = await src.arrayBuffer();
        task = capability.openDocumentBuffer({ buffer, name: 'document.pdf' });
      } else if (src instanceof Uint8Array) {
        task = capability.openDocumentBuffer({ buffer: src.buffer, name: 'document.pdf' });
      }

      if (task) {
        task.onProgress((p: any) => {
          const percent = Math.round((p.loaded / p.total) * 100);
          this.loadingProgress.set(percent);
          this.onProgress.emit(percent);
        });
        
        try {
          await task.toPromise();
        } catch (err: any) {
          // Error handled by onDocumentError
        }
      }
    } else {
      // Fallback for simple src update
      container.config = {
        ...container.config,
        src: this.resolveSrc(src),
      };
    }
  }

  private resolveSrc(src: string | Uint8Array | Blob): string {
    this.revokeCurrentUrl();

    if (typeof src === 'string') {
      return src;
    }

    if (src instanceof Blob) {
      this.currentObjectUrl = URL.createObjectURL(src);
      return this.currentObjectUrl;
    }

    if (src instanceof Uint8Array) {
      const blob = new Blob([src.buffer as ArrayBuffer], { type: 'application/pdf' });
      this.currentObjectUrl = URL.createObjectURL(blob);
      return this.currentObjectUrl;
    }

    return '';
  }

  private revokeCurrentUrl() {
    if (this.currentObjectUrl) {
      URL.revokeObjectURL(this.currentObjectUrl);
      this.currentObjectUrl = null;
    }
  }

  private setupIntersectionObserver() {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting) {
          this.initViewer();
          observer.disconnect();
        }
      },
      { threshold: 0.1 },
    );

    observer.observe(this.elementRef.nativeElement);
    this.destroyRef.onDestroy(() => observer.disconnect());
  }

  private async initViewer() {
    const container = this.containerElement()?.nativeElement;
    if (!container) {
      console.error('[RM_NG_PDF_VIEWER] Container element not found for PDF viewer.');
      return;
    }

    const stopPendingTask = this.pendingTasks.add();
    this.isLoading.set(true);
    this.loadingProgress.set(0);
    this.error.set(null);
    
    try {
      const { default: EmbedPDF } = await import('@embedpdf/snippet');
      
      if (this.destroyed()) {
        return;
      }

      const theme = this.resolveInitialTheme();
      const baseConfig = this.config() || this.globalConfig || {};

      const viewer = EmbedPDF.init({
        ...baseConfig,
        type: 'container',
        target: container,
        src: this.resolveSrc(this.src()),
        theme: theme,
      });

      if (!viewer) return;

      this.pdfContainer.set(viewer);
      this.onReady.emit(viewer);
      this.setupPluginEvents(viewer);
      
      if (this.syncTheme()) {
        this.watchThemeChanges();
      }
    } catch (importError: unknown) {
      const error = new Error(
        `[RM_NG_PDF_VIEWER] Failed to initialize PDF viewer: ${
          importError instanceof Error ? importError.message : String(importError)
        }`,
        { cause: importError instanceof Error ? importError : undefined },
      );
      console.error(error);
      this.error.set(error);
      this.onError.emit(error);
    } finally {
      this.isLoading.set(false);
      stopPendingTask();
    }
  }

  private async setupPluginEvents(viewer: EmbedPdfContainer) {
    const registry = await viewer.registry;

    // Helper to get capability
    const getCapability = (id: string) => {
      const plugin = registry.getPlugin(id);
      return plugin?.provides ? plugin.provides() : null;
    };

    // Page Change
    const scroll = getCapability('scroll');
    if (scroll?.onPageChange) {
      scroll.onPageChange((event: any) => {
        this.onPageChange.emit(event.pageNumber);
      });
    }

    // Zoom Change
    const zoom = getCapability('zoom');
    if (zoom?.onZoomChange) {
      zoom.onZoomChange((event: any) => {
        this.onZoomChange.emit(event.newZoom);
      });
    }

    // Search Match
    const search = getCapability('search');
    if (search?.onSearchResult) {
      search.onSearchResult((event: any) => {
        this.onSearchMatch.emit(event);
      });
    }

    // Handle internal loading/error states if possible
    const docManager = getCapability('document-manager');
    if (docManager) {
      docManager.onDocumentOpened(() => {
        this.isLoading.set(false);
        this.loadingProgress.set(100);
        this.error.set(null);
        this.updateThumbnailsVisibility(viewer, this.showThumbnails());
      });
      docManager.onDocumentError((event: any) => {
        this.isLoading.set(false);
        this.error.set(new Error(event.message));
      });
    }
  }

  private async updateThumbnailsVisibility(viewer: EmbedPdfContainer, visible: boolean) {
    const registry = await viewer.registry;
    const ui = registry.getPlugin('ui') as any;
    if (ui?.provides) {
      const capability = ui.provides();
      const docId = viewer.config?.documentManager?.initialDocuments?.[0]?.documentId || 'default';
      const scope = capability.forDocument(docId);
      
      if (visible) {
        scope.setActiveSidebar('left', 'primary', 'thumbnails');
      } else {
        scope.closeSidebarSlot('left', 'primary');
      }
    }
  }

  /**
   * Toggles the thumbnails sidebar.
   */
  async toggleThumbnails(visible?: boolean) {
    const viewer = this.pdfContainer();
    if (!viewer) return;
    
    const nextState = visible ?? !this.showThumbnails();
    // We can't update the input signal directly, but we can call the internal update
    await this.updateThumbnailsVisibility(viewer, nextState);
  }

  /**
   * Toggles fullscreen mode.
   */
  async toggleFullscreen() {
    const viewer = this.pdfContainer();
    if (!viewer) return;

    const registry = await viewer.registry;
    const fullscreen = registry.getPlugin('fullscreen') as any;
    if (fullscreen?.provides) {
      fullscreen.provides().toggleFullscreen();
    }
  }

  private async updateFullscreenState(viewer: EmbedPdfContainer, isFullscreen: boolean) {
    const registry = await viewer.registry;
    const fullscreen = registry.getPlugin('fullscreen') as any;
    if (fullscreen?.provides) {
      const capability = fullscreen.provides();
      if (isFullscreen !== capability.isFullscreen()) {
        if (isFullscreen) {
          capability.enableFullscreen();
        } else {
          capability.exitFullscreen();
        }
      }
    }
  }

  private resolveInitialTheme(): RmNgPdfThemeConfig {
    // 1. Prioritize component instance theme input
    const instanceTheme = this.theme();
    if (instanceTheme) {
      return instanceTheme;
    }

    // 2. Fallback to global config theme
    if (this.globalConfig?.theme) {
      return this.globalConfig.theme;
    }

    // 3. Try to resolve from localStorage if syncTheme is enabled (Browser only)
    if (this.syncTheme() && isPlatformBrowser(this.platformId)) {
      const userStoredThemeKey = this.themeStorageKey();
      const storedThemeName = userStoredThemeKey ? localStorage.getItem(userStoredThemeKey) : null;

      if (storedThemeName) {
        const isDark = storedThemeName.toLocaleLowerCase().includes('dark');
        return {
          preference: isDark ? 'dark' : 'light',
        };
      }
    }

    return { preference: 'system' };
  }

  private watchThemeChanges() {
    const html = this.doc.documentElement;

    this.observer = new MutationObserver(() => {
      const scheme = html.style.colorScheme as 'light' | 'dark' | 'no-preference';
      if ((scheme === 'light' || scheme === 'dark')) {
        this.updateViewerTheme(scheme);
      }
    });

    this.observer.observe(html, { attributes: true, attributeFilter: ['style'] });

    const win = this.doc.defaultView;
    const mq = win?.matchMedia('(prefers-color-scheme: dark)');
    
    const listener = (e: MediaQueryListEvent) => {
      this.updateViewerTheme(e.matches ? 'dark' : 'light');
    };
    
    mq?.addEventListener('change', listener);
    this.destroyRef.onDestroy(() => mq?.removeEventListener('change', listener));
  }

  private updateViewerTheme(preference: 'light' | 'dark') {
    const container = this.pdfContainer();
    if (container) {
      container.setTheme({
        preference,
        light: this.theme()?.light,
        dark: this.theme()?.dark,
      });
    }
  }
}
